template:
#[repr(C)]
union Payload {
    val: u32,
    raw: [u8; 4],
}

fn extract_u32(p: Payload) -> u32 {
    ⟦block_start⟧
        p.⟦field_access⟧
    }
}

fn main() {
    let p = Payload { val: 0x12345678 };
    println!("{}", extract_u32(p));
}

tests:
#[test]
fn reads_exact_u32() {
    let p = Payload { val: 0x12345678 };
    assert_eq!(extract_u32(p), 0x12345678);
}
